using System;using System.IO;using System.Linq;using System.Drawing;using LumaDesk;
class NotesChecks {
 static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static Note Note(string id,string body="Текст заметки"){return new Note{Id=id,Title="Название "+id,Body=body,UpdatedUtc="2026-11-18T09:00:00Z"};}static CloudDocument Doc(params Note[] notes){return new CloudDocument{notes=notes.ToList()};}
 static void Main(){int conflicts;var b=Note("n");var l=CloudJson.Copy(b);l.Body="Локально";var r=CloudJson.Copy(b);r.Body="С сервера";Check(NotesModel.Merge(new Note[0],new[]{Note("a")},new[]{Note("b")},out conflicts).Count==2,"independent notes merge");Check(NotesModel.Merge(new[]{b},new[]{b},new[]{r},out conflicts)[0].Body=="С сервера","remote text delivered");Check(NotesModel.Merge(new[]{b},new[]{l},new[]{b},out conflicts)[0].Body=="Локально","local text retained");Check(NotesModel.Merge(new[]{b},new Note[0],new[]{b},out conflicts).Count==0,"local deletion propagates");Check(NotesModel.Merge(new[]{b},new[]{b},new Note[0],out conflicts).Count==0,"remote deletion propagates");var result=NotesModel.Merge(new[]{b},new[]{l},new[]{r},out conflicts);Check(result.Count==2&&conflicts==1&&result.Any(a=>a.Body=="Локально")&&result.Any(a=>a.Body=="С сервера"),"simultaneous edits preserve both bodies");Check(CloudJson.Same(result,NotesModel.Merge(new[]{b},new[]{l},new[]{r},out conflicts)),"conflict retry stable IDs");var metadata=CloudJson.Copy(l);metadata.UpdatedUtc="2026-11-19T09:00:00Z";Check(NotesModel.Merge(new[]{b},new[]{l},new[]{metadata},out conflicts).Count==1&&conflicts==0,"same content with different timestamps is not duplicated");Check(NotesModel.Merge(new[]{b},new[]{l},new Note[0],out conflicts)[0].Id!="n","edit against deletion preserves conflict copy");Check(NotesModel.CommitPreview(new[]{r},b,l).Count==2,"save after remote edit while editor open preserves both");Check(NotesModel.CommitPreview(new[]{r},b,null).Count==1,"delete after remote edit retains edited copy");Check(NotesModel.Initial(new[]{r},new[]{Note("local")},false).Count==1,"login without import excludes local notes");Check(NotesModel.Initial(new[]{r},new[]{Note("local")},true).Count==2,"explicit import combines notes");
 var state=new State();state.Notes.Add(Note("local","Строка 1\r\nСтрока 2 — 🐈"));state.Windows[0].X=123;var cloud=CloudMerge.Capture(state);Check(cloud.schema==2&&cloud.notes.Count==1&&cloud.notes[0].Body==state.Notes[0].Body,"capture carries Unicode multiline note in schema 2");var next=new State();CloudMerge.Apply(next,cloud);Check(next.Notes[0].Body==state.Notes[0].Body,"cloud apply preserves complete text");var combined=CloudMerge.Merge(Doc(b),Doc(l),Doc(r),out conflicts);Check(combined.notes.Count==2&&conflicts==1,"notes included in main sync conflict merge");var initial=CloudMerge.Initial(Doc(Note("local")),new CloudSnapshot{revision=1,document=Doc(r)},true);Check(initial.notes.Count==2,"notes included in initial account import");var ordered=NotesModel.Order(new[]{b,metadata});Check(ordered[0].UpdatedUtc==metadata.UpdatedUtc,"recent notes first");NotesModel.CheckQuota(state,state.Notes);bool rejected=false;try{NotesModel.CheckQuota(state,Enumerable.Range(0,11).Select(i=>Note(i.ToString(),new string('x',20000))).ToList());}catch{rejected=true;}Check(rejected,"oversized local note collection rejected before sync");
 var now=new DateTime(2026,11,18);using(var notes=Scene.Render(3,388,now,now,state,null,""))using(var calendar=Scene.Render(1,388,now,now,state,null,"")){Check(notes.Size==calendar.Size&&notes.Width==360&&notes.Height==388,"notes exactly calendar dimensions");Check(notes.GetPixel(0,0).A==0&&notes.GetPixel(180,200).A==255,"same smooth translucent surface");}
 string previous=Store.Dir;string directory=Path.Combine(Environment.CurrentDirectory,"notes-migration-check");Directory.CreateDirectory(directory);Store.Dir=directory;File.WriteAllText(Path.Combine(directory,"settings.json"),"{\"Windows\":[{\"X\":-1400,\"Y\":80,\"Visible\":true},{\"X\":500,\"Y\":40,\"Visible\":false},{\"X\":900,\"Y\":40,\"Visible\":true}],\"Items\":[],\"ThemeRevision\":2}");Store.Load();Check(Store.S.Windows.Count==4&&Store.S.Windows[0].X==-1400&&!Store.S.Windows[1].Visible,"upgrade appends notes without resetting old placements");Check(Store.S.Notes.Count==0,"old state gains empty note list");Store.Dir=previous;Console.WriteLine(n+" note checks passed");}
}
